import sympy

def build_instance(rng):
    constant = rng.randint(0, 10)
    x = sympy.symbols('x')
    equation = x ** 3 - 3 * x ** 2 + 2 * x - constant
    roots = sympy.solve(equation, x)
    answer = len([root for root in roots if root.is_real])
    check = sum((1 for _ in sympy.solve(equation, x) if sympy.im(_).is_zero))
    parameters = {'constant': constant}
    return (parameters, answer, check)



